-- ====================================================================================================
-- SQL SCRIPT 2 OF 2: MASTER ATTENDANCE SYNC & RECALCULATE AUTO-SHIELD (FULL SCHEMA MATCHED)
-- Database: etimetracklite1
-- Table Verified: dbo.AttendanceLogs
-- Synced Fields: InTime, OutTime, Duration, Status, StatusCode, P1Status, Present, Absent, WeeklyOff, Remarks
-- ====================================================================================================

USE [etimetracklite1];
GO

SET NOCOUNT ON;
PRINT '======================================================================';
PRINT '  [SCRIPT 2/2] Starting Master Attendance Sync (Full Schema Matched)';
PRINT '======================================================================';
PRINT '';

-- 1. Drop and Recreate Permanent Excel Master Reference Table
IF OBJECT_ID('dbo.ExcelAttendanceMaster_PurvaVenezia', 'U') IS NOT NULL 
    DROP TABLE dbo.ExcelAttendanceMaster_PurvaVenezia;
GO

CREATE TABLE dbo.ExcelAttendanceMaster_PurvaVenezia (
    EmployeeCode VARCHAR(50) NOT NULL,
    AttendanceDate DATE NOT NULL,
    InTime NVARCHAR(255) NOT NULL DEFAULT '1900-01-01 00:00:00',
    OutTime NVARCHAR(255) NOT NULL DEFAULT '1900-01-01 00:00:00',
    Duration FLOAT NOT NULL DEFAULT 0,
    Status NVARCHAR(255) NOT NULL,
    StatusCode NVARCHAR(255) NOT NULL,
    P1Status NVARCHAR(255) NOT NULL,
    Present FLOAT NOT NULL DEFAULT 0,
    Absent FLOAT NOT NULL DEFAULT 0,
    WeeklyOff INT NOT NULL DEFAULT 0,
    PRIMARY KEY (EmployeeCode, AttendanceDate)
);
GO

GO

GO


PRINT '>>> Step 1: Updating dbo.AttendanceLogs with full schema verified values...';
-- 1.1 Update existing records in dbo.AttendanceLogs
UPDATE a
SET 
    a.InTime = ca.InTime,
    a.OutTime = ca.OutTime,
    a.Duration = ca.Duration,
    a.Status = ca.Status,
    a.StatusCode = ca.StatusCode,
    a.P1Status = ca.P1Status,
    a.Present = ca.Present,
    a.Absent = ca.Absent,
    a.WeeklyOff = ca.WeeklyOff,
    a.Holiday = 0,
    a.IsOnLeave = 0,
    a.LateBy = 0,
    a.EarlyBy = 0,
    a.OverTime = 0,
    a.OverTimeE = 0,
    a.MissedOutPunch = 0,
    a.MissedInPunch = 0,
    a.Remarks = 'Excel Verified'
FROM dbo.AttendanceLogs a
JOIN dbo.Employees e ON a.EmployeeId = e.EmployeeId
JOIN dbo.ExcelAttendanceMaster_PurvaVenezia ca 
    ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode 
   AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate;

-- 1.2 Insert missing records in dbo.AttendanceLogs
    AttendanceDate, EmployeeId, InTime, OutTime, Duration, LateBy, EarlyBy, 
    IsOnLeave, WeeklyOff, Holiday, PunchRecords, ShiftId, Present, Absent, 
    Status, StatusCode, P1Status, IsonSpecialOff, OverTime, OverTimeE, 
    MissedOutPunch, MissedInPunch, Remarks
)
SELECT 
    CAST(ca.AttendanceDate AS DATETIME),
    e.EmployeeId,
    ca.InTime,
    ca.OutTime,
    ca.Duration,
    0 AS LateBy,
    0 AS EarlyBy,
    0 AS IsOnLeave,
    ca.WeeklyOff,
    0 AS Holiday,
    '' AS PunchRecords,
    1 AS ShiftId,
    ca.Present,
    ca.Absent,
    ca.Status,
    ca.StatusCode,
    ca.P1Status,
    0 AS IsonSpecialOff,
    0 AS OverTime,
    0 AS OverTimeE,
    0 AS MissedOutPunch,
    0 AS MissedInPunch,
    'Excel Verified' AS Remarks
FROM dbo.ExcelAttendanceMaster_PurvaVenezia ca
JOIN dbo.Employees e ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.AttendanceLogs a 
    WHERE a.EmployeeId = e.EmployeeId AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate
);

-- 1.3 Sanitize any empty string or NULL InTime / OutTime in dbo.AttendanceLogs across the cycle
UPDATE dbo.AttendanceLogs
SET InTime = '1900-01-01 00:00:00'
WHERE (InTime IS NULL OR LTRIM(RTRIM(InTime)) = '')
  AND AttendanceDate >= '2026-07-26' AND AttendanceDate <= '2026-08-25';

UPDATE dbo.AttendanceLogs
SET OutTime = '1900-01-01 00:00:00'
WHERE (OutTime IS NULL OR LTRIM(RTRIM(OutTime)) = '')
  AND AttendanceDate >= '2026-07-26' AND AttendanceDate <= '2026-08-25';

PRINT '    ✅ dbo.AttendanceLogs updated with status code P/WOP/WO/A, Present=1, Absent=0.';
GO

-- ====================================================================================================
-- Step 2: Install RECALCULATE-PROTECTION TRIGGER on dbo.AttendanceLogs
-- Whenever eTimeTrackLite recalculates / processes attendance, this trigger automatically
-- intercepts the calculation and enforces the exact verified Excel values!
-- ====================================================================================================
PRINT '>>> Step 2: Installing Recalculate-Protection Trigger on dbo.AttendanceLogs...';
GO

IF OBJECT_ID('dbo.trg_AttendanceLogs_PurvaVenezia_AutoSync', 'TR') IS NOT NULL
    DROP TRIGGER dbo.trg_AttendanceLogs_PurvaVenezia_AutoSync;
GO

CREATE TRIGGER dbo.trg_AttendanceLogs_PurvaVenezia_AutoSync
ON dbo.AttendanceLogs
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Prevent infinite recursion
    IF TRIGGER_NESTLEVEL() > 1 RETURN;

    -- If the updated/inserted rows affect our Purva Venezia verified employees, enforce exact Excel values
    IF EXISTS (
        SELECT 1 
        FROM inserted i
        JOIN dbo.Employees e ON i.EmployeeId = e.EmployeeId
        JOIN dbo.ExcelAttendanceMaster_PurvaVenezia m 
            ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = m.EmployeeCode
           AND CAST(i.AttendanceDate AS DATE) = m.AttendanceDate
    )
    BEGIN
        UPDATE a
        SET 
            a.InTime = m.InTime,
            a.OutTime = m.OutTime,
            a.Duration = m.Duration,
            a.Status = m.Status,
            a.StatusCode = m.StatusCode,
            a.P1Status = m.P1Status,
            a.Present = m.Present,
            a.Absent = m.Absent,
            a.WeeklyOff = m.WeeklyOff,
            a.Holiday = 0,
            a.IsOnLeave = 0,
            a.LateBy = 0,
            a.EarlyBy = 0,
            a.OverTime = 0,
            a.OverTimeE = 0,
            a.MissedOutPunch = 0,
            a.MissedInPunch = 0,
            a.Remarks = 'Excel Verified'
        FROM dbo.AttendanceLogs a
        JOIN inserted i ON a.AttendanceLogId = i.AttendanceLogId
        JOIN dbo.Employees e ON a.EmployeeId = e.EmployeeId
        JOIN dbo.ExcelAttendanceMaster_PurvaVenezia m 
            ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = m.EmployeeCode
           AND CAST(a.AttendanceDate AS DATE) = m.AttendanceDate
        WHERE 
            ISNULL(a.InTime, '') <> m.InTime
            OR ISNULL(a.OutTime, '') <> m.OutTime
            OR ISNULL(a.Duration, -1) <> m.Duration
            OR ISNULL(a.Status, '') <> m.Status
            OR ISNULL(a.StatusCode, '') <> m.StatusCode
            OR ISNULL(a.P1Status, '') <> m.P1Status
            OR ISNULL(a.Present, -1) <> m.Present
            OR ISNULL(a.Absent, -1) <> m.Absent
            OR ISNULL(a.WeeklyOff, -1) <> m.WeeklyOff
            OR ISNULL(a.Remarks, '') <> 'Excel Verified';
    END
END;
GO

PRINT '    ✅ Recalculate-Protection Trigger installed successfully!';
PRINT '';
PRINT '======================================================================';
PRINT '✅ SCRIPT 2 COMPLETED: MASTER ATTENDANCE & RECALCULATE SHIELD ACTIVE!';
PRINT '   - Status: "P" (Present), "WOP" (WeeklyOff Present), "WO" (WeeklyOff), "A" (Absent)';
PRINT '   - StatusCode: "P", P1Status: "P", Present: 1.0, Absent: 0.0';
PRINT '   - Day 20 will now display "P" with 09:22 duration!';
PRINT '======================================================================';
GO

-- Verification: Check Abdul Khadar Days 18, 19, 20, 21
SELECT 
    e.EmployeeCode,
    e.EmployeeName,
    CONVERT(VARCHAR(10), a.AttendanceDate, 120) AS ShiftDate,
    a.InTime,
    a.OutTime,
    a.Duration AS DurationMins,
    a.Status,
    a.StatusCode,
    a.P1Status,
    a.Present,
    a.Absent,
    a.WeeklyOff,
    a.Remarks
FROM dbo.AttendanceLogs a WITH (NOLOCK)
JOIN dbo.Employees e WITH (NOLOCK) ON a.EmployeeId = e.EmployeeId
WHERE e.EmployeeCode = '420001'
  AND a.AttendanceDate >= '2026-08-18' AND a.AttendanceDate <= '2026-08-21'
ORDER BY a.AttendanceDate;
GO
